import hashlib
import os
import sys

def collect(root: str, by_size: dict[int, list[str]]) -> None:
    try:
        names = sorted(os.listdir(root))
    except OSError:
        return
    for name in names:
        path = os.path.join(root, name)
        if os.path.islink(path):
            continue
        if os.path.isdir(path):
            collect(path, by_size)
        elif os.path.isfile(path):
            size = os.path.getsize(path)
            if size in by_size:
                by_size[size].append(path)
            else:
                by_size[size] = [path]


def main() -> None:
    by_size: dict[int, list[str]] = {}
    collect(sys.argv[1], by_size)
    buffers: list[bytes] = []
    for size in sorted(by_size):
        for path in by_size[size]:
            f = open(path, "rb")
            buffers.append(f.read())
            f.close()
    last = ""
    total = 0
    for i in range(8):
        for data in buffers:
            last = hashlib.sha256(data).hexdigest()
            total += len(last)
    print(total, last)

main()

fclone_lite.source:
# fclone-lite: print groups of identical files under a directory.
# The M6 driver (docs/roadmap.md#phase-5-m6-plan). This is the CPython
# version, the oracle for the Pythrust one; it keeps to what Pythrust
# plans to support, so the two can converge on one source.
import hashlib
import os
import sys


def collect(root: str, by_size: dict[int, list[str]]) -> None:
    try:
        names = sorted(os.listdir(root))
    except OSError:
        return
    for name in names:
        path = os.path.join(root, name)
        if os.path.islink(path):
            continue
        if os.path.isdir(path):
            collect(path, by_size)
        elif os.path.isfile(path):
            size = os.path.getsize(path)
            if size in by_size:
                by_size[size].append(path)
            else:
                by_size[size] = [path]


def digest(path: str) -> str:
    f = open(path, "rb")
    data = f.read()
    f.close()
    return hashlib.sha256(data).hexdigest()


def groups(paths: list[str]) -> list[list[str]]:
    by_hash: dict[str, list[str]] = {}
    for path in paths:
        try:
            h = digest(path)
        except OSError:
            continue
        if h in by_hash:
            by_hash[h].append(path)
        else:
            by_hash[h] = [path]
    found: list[list[str]] = []
    for h in sorted(by_hash):
        if len(by_hash[h]) > 1:
            found.append(by_hash[h])
    return found


def main() -> None:
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    by_size: dict[int, list[str]] = {}
    collect(root, by_size)
    first = True
    for size in sorted(by_size):
        if len(by_size[size]) < 2:
            continue
        for group in groups(by_size[size]):
            if not first:
                print()
            first = False
            print(size, "bytes:")
            for path in group:
                print(" ", path)


main()

fclone_tasks.source:
# fclone-lite with its hashing on tasks (M6c driver): every candidate
# (a file sharing its size with another) is hashed through one executor's
# `map`, so the pool starts once, not once per size group. Its output is
# fclone_lite.py's. Pythrust runs it unchanged, as CPython does.
import concurrent.futures
import hashlib
import os
import sys


def collect(root: str, by_size: dict[int, list[str]]) -> None:
    try:
        names = sorted(os.listdir(root))
    except OSError:
        return
    for name in names:
        path = os.path.join(root, name)
        if os.path.islink(path):
            continue
        if os.path.isdir(path):
            collect(path, by_size)
        elif os.path.isfile(path):
            size = os.path.getsize(path)
            if size in by_size:
                by_size[size].append(path)
            else:
                by_size[size] = [path]


def digest(path: str) -> str:
    # A task's exception would end `map`'s results, so an unreadable
    # file's digest is "", which no group takes.
    try:
        f = open(path, "rb")
        data = f.read()
        f.close()
    except OSError:
        return ""
    return hashlib.sha256(data).hexdigest()


def groups(paths: list[str], digests: list[str], start: int) -> list[list[str]]:
    by_hash: dict[str, list[str]] = {}
    for i in range(len(paths)):
        h = digests[start + i]
        if h == "":
            continue
        if h in by_hash:
            by_hash[h].append(paths[i])
        else:
            by_hash[h] = [paths[i]]
    found: list[list[str]] = []
    for h in sorted(by_hash):
        if len(by_hash[h]) > 1:
            found.append(by_hash[h])
    return found


def main() -> None:
    root = sys.argv[1] if len(sys.argv) > 1 else "."
    by_size: dict[int, list[str]] = {}
    collect(root, by_size)
    sizes: list[int] = []
    candidates: list[str] = []
    for size in sorted(by_size):
        if len(by_size[size]) < 2:
            continue
        sizes.append(size)
        for path in by_size[size]:
            candidates.append(path)
    with concurrent.futures.ThreadPoolExecutor() as ex:
        digests = list(ex.map(digest, candidates))
    # An open in a task can fail only because the pool's other tasks hold
    # files open (too many open files). Retry each failure one at a time
    # once the pool is gone, as fclone_lite.py reads, so both skip
    # exactly the files a lone read cannot open.
    for i in range(len(candidates)):
        if digests[i] == "":
            digests[i] = digest(candidates[i])
    start = 0
    first = True
    for size in sizes:
        for group in groups(by_size[size], digests, start):
            if not first:
                print()
            first = False
            print(size, "bytes:")
            for path in group:
                print(" ", path)
        start += len(by_size[size])


main()

